<script setup>
import { computed,onMounted,onUnmounted,ref,watch } from 'vue'
import { useRoute,useRouter,RouterLink } from 'vue-router'
import { assetUrl,useLearningStore } from '../api'
const route=useRoute(),router=useRouter(),api=useLearningStore()
const loading=ref(true),error=ref(''),busy=ref(false),now=ref(Date.now()),showAnswered=ref(false),serverOffset=ref(0),examAudio=ref(null),audioPlaying=ref(false),audioError=ref('')
let timer
const session=computed(()=>api.session?.id===route.params.id?api.session:null)
const questions=computed(()=>session.value?.questions||[])
const question=computed(()=>questions.value[session.value?.currentIndex||0])
const answer=computed(()=>(session.value?.answers||[]).find(a=>a.questionId===question.value?.id))
const exam=computed(()=>session.value?.examConfig)
const section=computed(()=>exam.value?.sections?.[exam.value.sectionIndex])
const remaining=computed(()=>{if(!exam.value?.deadline)return '—';const offset=serverOffset.value;const seconds=Math.max(0,Math.ceil((Date.parse(exam.value.deadline)-now.value-offset)/1000));return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`})
const wrong=computed(()=>(session.value?.answers||[]).filter(a=>a.isCorrect===false))
function optionText(q,id){return q?.options?.find(o=>o.id===id)?.content||'—'}
async function load(){loading.value=true;error.value='';try{await api.loadSession(route.params.id);serverOffset.value=Date.parse(api.session.serverNow)-Date.now()}catch(e){error.value=e.message}finally{loading.value=false}}
onMounted(()=>{load();timer=setInterval(()=>{now.value=Date.now();if(exam.value?.deadline&&Date.parse(exam.value.deadline)<=now.value&&!busy.value&&session.value&&!session.value.completedAt)load()},1000)})
onUnmounted(()=>clearInterval(timer));watch(()=>route.params.id,load)
async function act(fn){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message;await api.loadSession(route.params.id).catch(()=>{})}finally{busy.value=false}}
function choose(optionId){if(!question.value||answer.value)return;act(()=>api.answer(route.params.id,question.value.id,optionId))}
function submitSection(){if(confirm('提前提交本科目？提交后不能返回，未答题按错误计分。'))act(()=>api.section(route.params.id,'submit'))}
async function playExamAudio(){try{const audio=examAudio.value;if(!audio)return;const elapsed=Math.max(0,(now.value+serverOffset.value-Date.parse(exam.value.sectionStartedAt))/1000);if(audio.readyState<1)await new Promise((resolve,reject)=>{audio.addEventListener('loadedmetadata',resolve,{once:true});audio.addEventListener('error',reject,{once:true})});audio.currentTime=Math.min(elapsed,Math.max(0,audio.duration-0.1));await audio.play();audioPlaying.value=true;audioError.value=''}catch{audioError.value='浏览器需要点击后才能播放，或音频暂不可用。计时仍在继续。'}}
function back(){router.push(session.value?.mode==='fun'?'/fun':'/mock-exam')}
</script>
<template><div class="session-shell"><div class="session-top"><button @click="back">← 返回学习页</button><strong>山间书院 · {{session?.mode==='exam'?'模拟考试':'趣味练习'}}</strong><button v-if="session" @click="showAnswered=!showAnswered">已答 {{session.answers?.length||0}} 题</button></div><div class="session-body"><div v-if="loading" class="state-box">正在读取练习…</div><div v-else-if="error&&!session" class="state-box error">{{error}} <button @click="load">重试</button></div><template v-else-if="session"><div v-if="error" class="state-box error">{{error}}</div><template v-if="session.completedAt"><p class="eyebrow">SESSION COMPLETED</p><h1>练习已完成</h1><div class="score-panel"><strong>{{session.score}}<small> / 100 分</small></strong><p>答对 {{session.correctCount}} / {{session.totalQuestions}} 题 · 答错 {{wrong.length}} 题</p><p>总分由后端根据首次作答计算并保存。{{session.mode==='exam'?'此分数是练习正确率，不是 JLPT 官方量尺成绩。':''}}</p></div><h2>{{wrong.length?'本次错题回顾':'本次全部答对'}}</h2><article v-for="a in wrong" :key="a.questionId" class="answer-review"><h3>{{questions.find(q=>q.id===a.questionId)?.content}}</h3><p>你的答案：{{optionText(questions.find(q=>q.id===a.questionId),a.selectedOptionId)}}</p><p>正确答案：{{optionText(questions.find(q=>q.id===a.questionId),a.correctOptionId)}}</p><p>{{a.explanation?.sentenceStructure||'该题暂未收录讲解'}}</p></article><button class="primary-action" @click="back">返回学习页</button></template><template v-else-if="exam?.waitingSection"><p class="eyebrow">SECTION COMPLETED</p><h1>本科目已交卷</h1><p>下一科：{{exam.sections?.[exam.sectionIndex+1]?.title}} · {{exam.sections?.[exam.sectionIndex+1]?.minutes}} 分钟</p><button class="primary-action" :disabled="busy" @click="act(()=>api.section(route.params.id,'start'))">开始下一科 ↗</button></template><template v-else-if="question"><div class="session-progress"><span>{{session.currentIndex+1}} / {{questions.length}}</span><div><span :style="{width:`${(session.answers?.length||0)/questions.length*100}%`}"></span></div></div><div v-if="exam" class="exam-clock"><strong>{{section?.title}}</strong><span>剩余 {{remaining}}</span><button :disabled="busy" @click="submitSection">提前提交本科目</button><p>{{exam.instantFeedback?'错题立即讲解已开启；查看讲解仍计时。':'严格计时；交卷后统一查看答案和讲解。'}}</p><div v-if="section?.audioUrl||question.audioUrl" class="exam-audio"><audio ref="examAudio" :src="assetUrl(section?.audioUrl||question.audioUrl)" @ended="audioPlaying=false"></audio><button v-if="!audioPlaying" type="button" @click="playExamAudio">开始听力（从当前考试时间恢复）</button><span v-else>听力音频播放中 · 不提供暂停或倒带</span><small v-if="audioError">{{audioError}}</small></div></div><article class="question-panel"><small>{{question.level==='ungraded'?'素材练习':question.level?.toUpperCase()}} · {{question.type}}</small><img v-if="question.contentImageUrl" class="question-image" :src="assetUrl(question.contentImageUrl)" alt="题目原图"><details v-if="question.provenance?.kind==='user_material'" :open="question.provenance?.collection!=='novel'"><summary>原文线索：{{question.provenance.title}}</summary><p class="reading-text">{{question.provenance.passage}}</p></details><h1>{{question.content}}</h1><p v-if="question.provenance" class="source-caption">{{question.provenance.kind==='user_material'?'素材改编 · 非官方真题':'官方问题集'}} · {{question.provenance.filename||''}} 第 {{question.provenance.pdfPage||''}} 页</p></article><div class="options"><button v-for="(o,i) in question.options||[]" :key="o.id" :class="{correct:answer?.correctOptionId===o.id,wrong:answer?.selectedOptionId===o.id&&answer?.isCorrect===false,selected:answer?.selectedOptionId===o.id}" :disabled="busy||!!answer" @click="choose(o.id)"><span>{{String.fromCharCode(65+i)}}</span>{{o.content}}</button></div><div v-if="session.awaitingNext&&answer" class="answer-review"><strong>{{answer.isCorrect?'回答正确':'回答错误 · 本题已锁定'}}</strong><p>你的答案：{{optionText(question,answer.selectedOptionId)}}</p><p>正确答案：{{optionText(question,answer.correctOptionId)}}</p><p>{{answer.explanation?.sentenceStructure||'该题暂未收录讲解'}}</p><small v-if="answer.explanation?.note">{{answer.explanation.note}}</small><button class="primary-action" :disabled="busy" @click="act(()=>api.next(route.params.id))">{{session.currentIndex+1===questions.length?'查看总分':'下一题'}} ↗</button></div></template><div v-if="showAnswered" class="answered-drawer"><button @click="showAnswered=false">关闭 ×</button><h2>已答记录</h2><p>首次答案已锁定，仅可回看。</p><article v-for="a in session.answers||[]" :key="a.questionId"><strong>{{questions.find(q=>q.id===a.questionId)?.content}}</strong><p>你的答案：{{optionText(questions.find(q=>q.id===a.questionId),a.selectedOptionId)}}</p><p v-if="a.isCorrect!==undefined">{{a.isCorrect?'回答正确':'回答错误'}} · {{a.explanation?.sentenceStructure}}</p></article></div></template></div></div></template>
